    21: "MA", 22: "PI", 23: "CE", 24: "RN", 25: "PB", 26: "PE", 27: "AL",
    28: "SE", 29: "BA", 31: "MG", 32: "ES", 33: "RJ", 35: "SP", 41: "PR",
    42: "SC", 43: "RS", 50: "MS", 51: "MT", 52: "GO", 53: "DF",
}
REGION_BY_UF = {
    **{uf: "Norte" for uf in "RO AC AM RR PA AP TO".split()},
    **{uf: "Nordeste" for uf in "MA PI CE RN PB PE AL SE BA".split()},
    **{uf: "Sudeste" for uf in "MG ES RJ SP".split()},
    **{uf: "Sul" for uf in "PR SC RS".split()},
    **{uf: "Centro-Oeste" for uf in "MS MT GO DF".split()},
}

DATES = ["30 mar.", "27 abr.", "25 mai.", "15 jun.", "29 jun.", "13 jul.", "27 jul.", "3 ago."]
SERIES = {
    "dates": DATES,
    "first": {"Lula": [41, 41, 40, 42, 42, 40, 42, 41], "Flávio": [38, 36, 35, 33, 34, 34, 33, 37]},
    "runoff": {"Lula": [46, 46, 47, 49, 47, 47, 47, 46], "Flávio": [46, 45, 43, 43, 44, 44, 43, 45]},
    "spontaneous": {"Lula": [32, 33, 36, 36, 38, 35, 36, 36], "Flávio": [26, 26, 26, 27, 27, 24, 27, 28]},
}

TOPLINES = {
    "july": {
        "first": [42, 33, 6, 5, 3, 2, 1, 0, 6, 2],
        "runoff": [47, 43, 9, 1],
        "labels": ["Lula", "Flávio", "Caiado", "Renan", "Zema", "Cury", "Daciolo", "Samara", "B/N", "NS"],
    },
    "august": {
        "first": [41, 37, 5, 4, 3, 1, 1, 1, 4, 3],
        "runoff": [46, 45, 8, 2],
        "labels": ["Lula", "Flávio", "Caiado", "Renan", "Zema", "Cury", "Daciolo", "Samara", "B/N", "NS"],
    },
}

PROFILES = {
    "july": {
        "sex": [53, 47], "age": [12, 30, 34, 24], "education": [36, 41, 23],
        "income": [23, 17, 40, 20], "region": [16, 28, 42, 14],
    },
    "august": {
        "sex": [53, 47], "age": [12, 30, 34, 24], "education": [36, 41, 23],
        "income": [22, 18, 40, 21], "region": [16, 28, 42, 14],
