# Cell order: candidates, then blank/null and undecided. Values are published rounded percentages.
CROSSTABS = {
    "july": {
        "first": {
            "income": [[58, 24, 3, 3, 1, 1, 1, 0, 7, 3], [47, 30, 5, 5, 2, 2, 1, 0, 5, 3],
                       [36, 38, 7, 6, 4, 2, 1, 0, 5, 1], [34, 37, 9, 4, 5, 3, 2, 0, 5, 1]],
        },
        "runoff": {
