                       [38, 39, 5, 4, 4, 4, 4, 2], [39, 38, 5, 5, 5, 3, 3, 2]],
            "region": [[40, 34, 10, 3, 3, 5, 2, 3], [48, 34, 4, 5, 1, 3, 3, 2],
                       [42, 35, 3, 3, 5, 4, 4, 4], [27, 51, 5, 4, 2, 3, 6, 1]],
