            "education": [[47, 43, 6, 3], [44, 45, 9, 2], [46, 45, 8, 1]],
            "income": [[58, 32, 6, 4], [43, 49, 7, 1], [42, 47, 10, 2], [43, 50, 7, 1]],
            "region": [[44, 48, 6, 2], [52, 39, 7, 1], [47, 42, 8, 3], [32, 57, 9, 1]],
        },
