footer .wrap { display: flex; justify-content: space-between; gap: 30px; }
footer b { color: white; }

.js .reveal { opacity: 0; transform: translateY(22px); transition: opacity .65s ease, transform .65s ease; }
.js .reveal.visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) { .js .reveal { opacity: 1; transform: none; transition: none; } }

@media (max-width: 840px) {
  .topbar nav { display: none; }
  .hero { min-height: 80vh; }
  .hero-ledger { grid-template-columns: repeat(2, 1fr); gap: 20px 0; }
  .section-head, .signal .wrap { grid-template-columns: 1fr; gap: 10px; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .flow-grid { grid-template-columns: 1fr; }
  .flow-stage { min-height: 360px; }
  .method-rail { grid-template-columns: 1fr; }
  .method-step { min-height: 0; }
  .source-list li { grid-template-columns: 45px 1fr; }
  .source-list small { grid-column: 2; }
  footer .wrap { flex-direction: column; }
}

@media (max-width: 520px) {
  body { font-size: 16px; }
  .wrap { width: min(100% - 24px, var(--max)); }
  h1 { font-size: 48px; }
  main section { padding: 64px 0; }
  .hero-content { padding: 84px 0 52px; }
  .scoreboard { grid-template-columns: 1fr 20px 1fr; padding: 22px 10px; gap: 8px; }
  .score b { font-size: 60px; }
  .card, .chart-shell { padding: 20px; }
  .delta-table { font-size: 12px; }
  .delta-table th, .delta-table td { padding: 10px 6px; }
}

